export function learnerWords(value) {
  return String(value).normalize('NFKC').replace(/[’‘]/g,"'").toLowerCase()
    .match(/[a-z]+|\d+(?:\.\d+)?/g) ?? [];
}
const phrase = text => learnerWords(text).map(word => plurals.has(word) ? word.slice(0, -1) : word).join(' ');
const bounded = (text, query) => (' ' + text + ' ').includes(' ' + query + ' ');
